+  top: 0;
+  outline: 3px solid var(--border-focus);
+  outline-offset: 2px;
+}
+
+/* ===== Header ===== */
+header {
+  padding: 1rem 1.5rem;
+  background: var(--surface);
+  border-bottom: 1px solid var(--border);
+}
+.site-name {
+  font-size: 1rem;
+  font-weight: 700;
+  letter-spacing: 0.04em;
+  color: var(--accent);
+  text-transform: uppercase;
+}
+
+/* ===== Main layout ===== */
+main {
+  max-width: 540px;
+  margin: 3rem auto;
+  padding: 0 1rem;
+}
+
+h1 {
+  font-size: 1.75rem;
+  font-weight: 700;
+  color: var(--text-primary);
+  margin-bottom: 0.5rem;
+}
+
+.intro {
+  color: var(--text-muted);
+  margin-bottom: 2rem;
+}
+
+/* ===== Form card ===== */
+form {
+  background: var(--surface);
+  border: 1px solid var(--border);
+  border-radius: var(--radius-lg);
+  padding: 2rem;
+  display: flex;
+  flex-direction: column;
+  gap: 1.5rem;
+}
+
+.required-note {
+  font-size: 0.8125rem;
+  color: var(--text-muted);
+}
+.required-note span {
+  color: var(--error);
+  margin-right: 0.2em;
+}
+
+/* ===== Form field ===== */
+.form-field {
+  display: flex;
+  flex-direction: column;
+  gap: 0.375rem;
+}
+
+label {
+  font-size: 0.9375rem;
+  font-weight: 600;
+  color: var(--text-primary);
+}
+
+.required-marker {
+  color: var(--error);
+  margin-left: 0.15em;
+}
+
+.optional-marker {
+  font-weight: 400;
+  color: var(--text-muted);
+  font-size: 0.875rem;
+}
+
+/* ===== Inputs ===== */
+input[type="text"],
+input[type="email"],
+input[type="tel"] {
+  width: 100%;
+  padding: 0.625rem 0.875rem;
+  background: var(--surface-alt);
+  color: var(--text-primary);
+  border: 1.5px solid var(--border);
+  border-radius: var(--radius-sm);
+  font-size: 1rem;
+  font-family: inherit;
+  transition: border-color 0.15s, box-shadow 0.15s;
+  appearance: none;
+}
+
+input::placeholder {
+  color: var(--text-muted);
+}
+
+input:focus {
+  outline: none;
+  border-color: var(--border-focus);
+  box-shadow: 0 0 0 3px rgba(91, 138, 245, 0.25);
+}
+
+input[aria-invalid="true"] {
+  border-color: var(--error);
+  background: var(--error-bg);
+}
+input[aria-invalid="true"]:focus {
+  border-color: var(--error);
+  box-shadow: 0 0 0 3px rgba(248, 113, 113, 0.25);
+}
+
+/* ===== Help & error text ===== */
+.help-text {
+  font-size: 0.8125rem;
+  color: var(--text-muted);
+}
+
+.error-message {
+  font-size: 0.8125rem;
+  color: var(--error);
+  font-weight: 500;
+}
+
+/* ===== Submit button ===== */
+button[type="submit"] {
+  align-self: flex-start;
+  padding: 0.6875rem 1.75rem;
+  background: var(--accent);
+  color: #fff;
+  border: none;
+  border-radius: var(--radius-sm);
+  font-size: 1rem;
+  font-weight: 600;
+  font-family: inherit;
+  cursor: pointer;
+  transition: background 0.15s, box-shadow 0.15s;
+}
+
+button[type="submit"]:hover {
+  background: var(--accent-hover);
+}
+
+button[type="submit"]:focus-visible {
+  outline: 3px solid var(--border-focus);
+  outline-offset: 3px;
+}
+
+/* ===== Success panel ===== */
+.success-panel {
+  background: var(--success-bg);
+  border: 1.5px solid var(--success);
+  border-radius: var(--radius-lg);
+  padding: 2rem;
+  display: flex;
+  flex-direction: column;
+  align-items: center;
+  gap: 0.75rem;
+  text-align: center;
+}
+
+.success-icon {
+  width: 3rem;
+  height: 3rem;
+  color: var(--success);
+  flex-shrink: 0;
+}
+
+.success-panel h2 {
+  font-size: 1.375rem;
+  font-weight: 700;
+  color: var(--success);
+}
+
+.success-panel p {
+  color: var(--text-muted);
+  max-width: 32ch;
+}
+
+/* ===== Visually hidden (for live regions) ===== */
+.visually-hidden {
+  position: absolute;
+  width: 1px;
+  height: 1px;
+  padding: 0;
+  overflow: hidden;
+  clip: rect(0,0,0,0);
+  white-space: nowrap;
+  border: 0;
+}
