import { chromium } from 'playwright';
import { readFileSync } from 'fs';
import path from 'path';

const BASE = '/workspace/sandbox/skills/building-accessible-ui/simple-contact-form--framework-vanilla-js--style-dark--validation-message-present/claude-sonnet-4.6__s3';
const html = readFileSync(path.join(BASE, 'index.html'), 'utf8')
  // Rewrite relative links so CSS/JS load from disk
  .replace(/href="styles\.css"/, `href="file://${BASE}/styles.css"`)
  .replace(/src="form\.js"/, `src="file://${BASE}/form.js"`);

const axeJs = readFileSync('/tmp/axe.min.js', 'utf8');

async function runAxe(label, setupFn) {
  const browser = await chromium.launch();
  const page = await browser.newPage();
  await page.setContent(html, { waitUntil: 'load' });
  await page.addScriptTag({ content: axeJs });
  if (setupFn) await setupFn(page);
  const result = await page.evaluate(async () => await window.axe.run());
  await browser.close();
  return { label, result };
}

async function main() {
  // State 1: Initial form
  const s1 = await runAxe('initial form');

  // State 2: Submit with empty fields to trigger validation errors
  const s2 = await runAxe('after submit with errors', async (page) => {
    await page.click('button[type="submit"]');
    await page.waitForTimeout(200);
  });

  const states = [s1, s2];
  let exitCode = 0;

  for (const { label, result } of states) {
    const wcag = result.violations.filter(v => !v.tags.includes('best-practice'));
    const bp   = result.violations.filter(v =>  v.tags.includes('best-practice'));

    console.log(`\n=== ${label} ===`);
    if (wcag.length === 0) {
      console.log('WCAG violations: none');
    } else {
      exitCode = 1;
      for (const v of wcag) {
        console.log(`FAIL [${v.impact}] ${v.id}: ${v.description}`);
        for (const n of v.nodes) {
          console.log(`  target: ${JSON.stringify(n.target)}`);
          console.log(`  fix: ${n.failureSummary?.split('\n')[0]}`);
        }
      }
    }
    if (bp.length > 0) {
      console.log('Best-practice warnings:');
      for (const v of bp) console.log(`  warn  ${v.id}: ${v.description}`);
    }
  }

  process.exit(exitCode);
}

main().catch(e => { console.error(e); process.exit(2); });
