*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

:root {
  --bg:          #0f1117;
  --surface:     #1a1d27;
  --surface-alt: #22263a;
  --border:      #2e3350;
  --border-focus:#5b8af5;
  --text-primary:#e8ecf4;
  --text-muted:  #8892aa;
  --accent:      #5b8af5;
  --accent-hover:#7aa3ff;
  --error:       #f87171;
  --error-bg:    #2d1a1a;
  --success:     #4ade80;
  --success-bg:  #0d2518;

  --radius-sm:   6px;
  --radius-md:   10px;
  --radius-lg:   14px;

  font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  font-size: 16px;
  line-height: 1.5;
  color: var(--text-primary);
  background-color: var(--bg);
}

/* ===== Skip link ===== */
.skip-link {
  position: absolute;
  top: -3rem;
  left: 1rem;
  z-index: 100;
  padding: 0.5rem 1rem;
  background: var(--accent);
  color: #fff;
  border-radius: 0 0 var(--radius-sm) var(--radius-sm);
  font-weight: 600;
  text-decoration: none;
  transition: top 0.15s;
}
.skip-link:focus {
  top: 0;
  outline: 3px solid var(--border-focus);
  outline-offset: 2px;
}

/* ===== Header ===== */
header {
  padding: 1rem 1.5rem;
  background: var(--surface);
  border-bottom: 1px solid var(--border);
}
.site-name {
  font-size: 1rem;
  font-weight: 700;
  letter-spacing: 0.04em;
  color: var(--accent);
  text-transform: uppercase;
}

/* ===== Main layout ===== */
main {
  max-width: 540px;
  margin: 3rem auto;
  padding: 0 1rem;
}

h1 {
  font-size: 1.75rem;
  font-weight: 700;
  color: var(--text-primary);
  margin-bottom: 0.5rem;
}

.intro {
  color: var(--text-muted);
  margin-bottom: 2rem;
}

/* ===== Form card ===== */
form {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 2rem;
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
}

.required-note {
  font-size: 0.8125rem;
  color: var(--text-muted);
}
.required-note span {
  color: var(--error);
  margin-right: 0.2em;
}

/* ===== Form field ===== */
.form-field {
  display: flex;
  flex-direction: column;
  gap: 0.375rem;
}

label {
  font-size: 0.9375rem;
  font-weight: 600;
  color: var(--text-primary);
}

.required-marker {
  color: var(--error);
  margin-left: 0.15em;
}

.optional-marker {
  font-weight: 400;
  color: var(--text-muted);
  font-size: 0.875rem;
}

/* ===== Inputs ===== */
input[type="text"],
input[type="email"],
input[type="tel"] {
  width: 100%;
  padding: 0.625rem 0.875rem;
  background: var(--surface-alt);
  color: var(--text-primary);
  border: 1.5px solid var(--border);
  border-radius: var(--radius-sm);
  font-size: 1rem;
  font-family: inherit;
  transition: border-color 0.15s, box-shadow 0.15s;
  appearance: none;
}

input::placeholder {
  color: var(--text-muted);
}

input:focus {
  outline: none;
  border-color: var(--border-focus);
  box-shadow: 0 0 0 3px rgba(91, 138, 245, 0.25);
}

input[aria-invalid="true"] {
  border-color: var(--error);
  background: var(--error-bg);
}
input[aria-invalid="true"]:focus {
  border-color: var(--error);
  box-shadow: 0 0 0 3px rgba(248, 113, 113, 0.25);
}

/* ===== Help & error text ===== */
.help-text {
  font-size: 0.8125rem;
  color: var(--text-muted);
}

.error-message {
  font-size: 0.8125rem;
  color: var(--error);
  font-weight: 500;
}

/* ===== Submit button ===== */
button[type="submit"] {
  align-self: flex-start;
  padding: 0.6875rem 1.75rem;
  /* #2563eb on #fff = 4.95:1 — passes WCAG AA for normal text */
  background: #2563eb;
  color: #fff;
  border: none;
  border-radius: var(--radius-sm);
  font-size: 1rem;
  font-weight: 600;
  font-family: inherit;
  cursor: pointer;
  transition: background 0.15s, box-shadow 0.15s;
}

button[type="submit"]:hover {
  background: #1d4ed8;
}

button[type="submit"]:focus-visible {
  outline: 3px solid var(--border-focus);
  outline-offset: 3px;
}

/* ===== Success panel ===== */
.success-panel {
  background: var(--success-bg);
  border: 1.5px solid var(--success);
  border-radius: var(--radius-lg);
  padding: 2rem;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.75rem;
  text-align: center;
}

.success-icon {
  width: 3rem;
  height: 3rem;
  color: var(--success);
  flex-shrink: 0;
}

.success-panel h2 {
  font-size: 1.375rem;
  font-weight: 700;
  color: var(--success);
}

.success-panel p {
  color: var(--text-muted);
  max-width: 32ch;
}

/* ===== Visually hidden (for live regions) ===== */
.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  overflow: hidden;
  clip: rect(0,0,0,0);
  white-space: nowrap;
  border: 0;
}

/* ===== Forced Colors (Windows HC / Contrast More) ===== */
@media (forced-colors: active) {
  input[aria-invalid="true"] {
    border-color: LinkText;
  }
  .error-message  { forced-color-adjust: none; color: LinkText; }
  .success-panel  { border-color: Highlight; }
  button[type="submit"] { forced-color-adjust: none; }
}

/* ===== Reduced motion ===== */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { transition: none !important; }
}

/* ===== Reflow — 320 px viewport ===== */
@media (max-width: 400px) {
  main { margin: 1.5rem auto; }
  form { padding: 1.25rem; }
  button[type="submit"] { width: 100%; text-align: center; align-self: stretch; }
}
